@import "../../shared/tokens.css";

/* step1 only: layout, question workflow, question card, ambiguity ledger, result. Values come from tokens.css. */

/* ---------- layout: one column (720px) plus the ledger rail on wide screens ---------- */
.layout { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-lg); max-width: 720px; margin-inline: auto; }
.layout__main { display: grid; align-content: start; gap: var(--space-lg); min-width: 0; }
.layout__main > .page-head { margin-bottom: 0; }
@media (min-width: 64rem) {
  .layout { max-width: none; grid-template-columns: minmax(0, 720px) minmax(0, 300px); justify-content: center; align-items: start; gap: var(--space-xl); }
  .layout__side { position: sticky; top: calc(var(--header-h) + var(--space-lg)); }
}
.prompt-title { font-size: var(--text-xl); }

/* ---------- home ---------- */
.start__body { display: grid; gap: var(--space-lg); }
.start__input { min-height: calc(var(--control-h) * 3.6); font-size: var(--text-lg); }
.start__examples { display: grid; gap: var(--space-xs); }
.start__list { display: flex; flex-wrap: wrap; gap: var(--space-2xs); margin: 0; padding: 0; list-style: none; }
.start__list .btn { white-space: normal; text-align: left; line-height: 1.4; border-color: var(--color-rule); }
.sessions { display: grid; gap: var(--space-md); margin: 0; padding: 0; list-style: none; }
.sessions li { display: grid; gap: var(--space-3xs); min-width: 0; }
.sessions li + li { padding-top: var(--space-md); border-top: var(--rule-hair) solid var(--color-rule); }
.sessions__link { border-radius: var(--radius-mark); color: var(--color-accent-text); font-weight: 500; overflow-wrap: anywhere; }
.sessions__link:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }

/* ---------- question workflow: numbered nodes joined by a connector ---------- */
.flow { display: grid; margin: 0; padding: 0; list-style: none; }
.flow__step { position: relative; display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: var(--space-sm); padding-bottom: var(--space-lg); }
.flow__step::before { content: ""; position: absolute; top: 32px; bottom: var(--space-2xs); left: 13px; border-left: 2px solid var(--color-edge); }
.flow__step:last-child { padding-bottom: 0; }
.flow__step:last-child::before { content: none; }
.flow__step--current::before { border-left-color: var(--color-edge-active); }
.flow__node {
  display: grid; place-items: center; width: 28px; height: 28px;
  border: var(--rule-hair) solid var(--color-rule-2); border-radius: var(--radius-mark);
  background: var(--color-surface); color: var(--color-ink-2); font-size: var(--text-xs); font-weight: 600;
}
.flow__node svg { width: 14px; height: 14px; }
.flow__step--current .flow__node { border-color: var(--color-accent); background: var(--color-accent-wash); color: var(--color-accent-text); }
.flow__body { min-width: 0; padding-top: var(--space-3xs); }
.flow__track { display: inline-block; margin-left: var(--space-xs); padding: 0 var(--space-2xs); border-radius: var(--radius-mark); background: var(--color-paper-3); color: var(--color-ink-2); font-size: var(--text-xs); font-weight: 500; line-height: 1.6; }
.flow--result { margin-top: calc(var(--space-md) * -1); }

/* ---------- current question card ---------- */
.qcard__body { display: grid; gap: var(--space-md); padding: var(--space-lg); }
.qcard--enter { animation: q-in var(--dur-short) var(--ease-out); }
@keyframes q-in { from { opacity: 0; transform: translateY(8px); } }
.qcard__q { font-size: var(--text-xl); }
.qcard__q:focus { outline: none; }
.qcard__q:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 4px; border-radius: var(--radius-mark); }
.qcard__hint { margin-top: calc(var(--space-xs) * -1); color: var(--color-ink-2); font-size: var(--text-sm); }
.qcard__text { min-height: calc(var(--control-h) * 1.8); }
.qcard__goal { font-size: var(--text-lg); font-weight: 500; }
.qcard__wrap { margin-left: auto; }
.qcard__skel-chip { min-height: var(--control-h); }
.chip__key { min-width: 1.2em; color: var(--color-muted); font-size: var(--text-xs); }
.chip--recommend { border-style: dashed; }

.decisions { display: grid; gap: var(--space-xs); margin: 0; }
.decisions > div { display: grid; grid-template-columns: minmax(0, 9em) minmax(0, 1fr); gap: var(--space-sm); padding-bottom: var(--space-xs); border-bottom: var(--rule-hair) solid var(--color-rule); font-size: var(--text-sm); }
.decisions dt { color: var(--color-muted); }
.decisions dd { margin: 0; }

/* ---------- ambiguity ledger ---------- */
.ledger .panel__body { display: grid; gap: var(--space-md); }
.ledger__total { display: grid; gap: var(--space-3xs); }
.ledger__num { font-size: var(--text-2xl); font-weight: 600; line-height: 1.1; }
.ledger__list { display: grid; gap: var(--space-2xs); margin: 0; padding: 0; list-style: none; }
.ledger__row {
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; column-gap: var(--space-xs); row-gap: var(--space-3xs);
  padding: var(--space-2xs) var(--space-xs); border-left: 2px solid transparent; border-radius: var(--radius-mark); font-size: var(--text-sm);
}
.ledger__row[aria-current="step"] { border-left-color: var(--color-accent); background: var(--color-accent-wash); }
.ledger__label { min-width: 0; }
.ledger__state { display: inline-flex; align-items: center; gap: var(--space-3xs); color: var(--color-muted); font-size: var(--text-xs); }
.ledger__state svg { width: 12px; height: 12px; }
.ledger__row[data-clear="true"] .ledger__state { color: var(--color-frozen); }
.ledger__score { color: var(--color-muted); font-size: var(--text-xs); }
.ledger__bar { grid-column: 1 / -1; height: 4px; overflow: hidden; border-radius: var(--radius-mark); background: var(--color-paper-3); }
.ledger__bar > span { display: block; height: 100%; background: var(--color-edge); transform-origin: left; transition: transform var(--dur-short) var(--ease-out); }
.ledger__row[data-clear="true"] .ledger__bar > span { background: var(--color-frozen); }

/* ---------- result ---------- */
.result__head { display: grid; gap: var(--space-sm); padding-bottom: var(--space-lg); border-bottom: var(--rule-hair) solid var(--color-rule); }
.result__title { font-size: var(--text-3xl); }
.result__tag { margin-left: var(--space-xs); color: var(--color-muted); font-size: var(--text-sm); font-weight: 500; letter-spacing: 0; vertical-align: middle; }
.result__one { color: var(--color-ink-2); font-size: var(--text-lg); }
.result .btn-row { margin-top: var(--space-xs); }
import type { Metadata } from 'next';
import { provider } from '@/lib/llm';
import './globals.css';

export const dynamic = 'force-dynamic'; // pages read SQLite and the LLM env at request time
export const metadata: Metadata = { title: '질문하기 - Super Planer', icons: { icon: '/super-planer-icon.svg' } };

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="ko">
      <body>
        <div className="app-shell">
          <header className="app-header">
            <a className="app-brand" href="/">
              <img src="/super-planer-icon.svg" alt="" width="28" height="28" />
              <span className="app-brand__name">Super Planer</span>
            </a>
            <nav className="app-nav" aria-label="PoC 이동">
              <ul>
                <li><a href="http://localhost:3101/" aria-current="page">질문하기</a></li>
                <li><a href="http://localhost:3102/">워크플로우</a></li>
                <li><a href="http://localhost:3103/">기획서</a></li>
              </ul>
            </nav>
            <p className="app-header__aside">LLM: {provider()}</p>
          </header>
          <main className="app-main">{children}</main>
        </div>
      </body>
    </html>
  );
}
import { listSessions } from '@/lib/session';
import StartForm from './StartForm';

const ERRORS: Record<string, string> = {
  short: '네 글자 이상 적어 주세요.',
  long: '1000자 이하로 줄여 주세요.',
  server: '세션을 만들지 못했어요. 다시 시도해 주세요.',
};

const when = (iso: string) => new Date(iso).toLocaleString('ko-KR', { month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });

export default async function Home({ searchParams }: { searchParams: Promise<{ error?: string }> }) {
  const { error } = await searchParams;
  const sessions = listSessions();
  return (
    <div className="layout">
      <div className="layout__main">
        <div className="page-head">
          <div className="page-head__text">
            <h1>어떤 게임을 만들고 싶나요?</h1>
            <p className="page-head__desc">대충 적어도 돼요. 질문에 하나씩 답하면 게임 이름과 설명으로 정리해 드려요.</p>
          </div>
        </div>
        <StartForm error={error ? ERRORS[error] ?? ERRORS.server : undefined} />
      </div>
      <section className="panel layout__side" aria-labelledby="recent-h">
        <header className="panel__head"><h2 className="panel__title" id="recent-h">최근 세션</h2></header>
        <div className="panel__body">
          {sessions.length ? (
            <ul className="sessions">
              {sessions.map((s) => (
                <li key={s.id}>
                  <a className="sessions__link" href={`/s/${s.id}`}>{s.title ?? s.prompt}</a>
                  <p className="meta">{s.status === 'done' ? '정리 완료' : `질문 중, 답 ${s.answered}개`}</p>
                  <p className="meta"><time dateTime={s.created_at}>{when(s.created_at)}</time></p>
                </li>
              ))}
            </ul>
          ) : (
            <div className="empty"><p>아직 세션이 없어요. 왼쪽에 아이디어를 적고 시작해 보세요.</p></div>
          )}
        </div>
      </section>
    </div>
  );
}
'use client';
import { useRef, useState } from 'react';
import { Clock } from './icons';

const EXAMPLES = [
  '고양이가 우주 농장을 운영하는 느긋한 게임',
  '좀비가 나오는 편의점에서 하룻밤 버티기',
  '친구랑 폰 하나로 번갈아 하는 짧은 퍼즐 대결',
  '꿈속을 돌아다니며 잃어버린 기억을 모으는 이야기',
];

// Plain form POST (works without JS); JS only fills examples, adds Ctrl/Cmd+Enter and the busy state.
export default function StartForm({ error }: { error?: string }) {
  const [prompt, setPrompt] = useState('');
  const [busy, setBusy] = useState(false);
  const ref = useRef<HTMLTextAreaElement>(null);
  return (
    <form className="start panel" action="/api/sessions" method="post" onSubmit={() => setBusy(true)} aria-busy={busy}>
      <div className="panel__body start__body">
        <div className="field">
          <label className="field__label" htmlFor="prompt">게임 아이디어</label>
          <textarea
            ref={ref} className="textarea start__input" id="prompt" name="prompt" rows={5} required minLength={4} maxLength={1000}
            placeholder="예: 고양이가 우주 농장을 운영하는 느긋한 게임" value={prompt} onChange={(e) => setPrompt(e.target.value)}
            aria-describedby={error ? 'prompt-help prompt-error' : 'prompt-help'} aria-invalid={error ? true : undefined}
            onKeyDown={(e) => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) e.currentTarget.form?.requestSubmit(); }}
          />
          <p className="field__help" id="prompt-help">한두 문장이면 충분해요. Ctrl+Enter로 바로 시작할 수 있어요.</p>
          {error && <p className="field__error" id="prompt-error">{error}</p>}
        </div>
        <div className="start__examples">
          <p className="meta" id="ex-label">이런 식으로 적어도 돼요</p>
          <ul className="start__list" aria-labelledby="ex-label">
            {EXAMPLES.map((ex) => (
              <li key={ex}><button type="button" className="btn btn--ghost btn--sm" onClick={() => { setPrompt(ex); ref.current?.focus(); }}>{ex}</button></li>
            ))}
          </ul>
        </div>
        {busy && <div className="notice" role="status"><Clock /><p>첫 질문을 만드는 중이에요. LLM을 쓰면 30초쯤 걸려요.</p></div>}
      </div>
      <footer className="panel__foot btn-row">
        <button type="submit" className="btn btn--primary" disabled={busy} aria-busy={busy}>질문 시작</button>
      </footer>
    </form>
  );
}
'use client';
import { useEffect, useRef, useState, type FormEvent, type KeyboardEvent } from 'react';
import { RECOMMEND, decisionOf, type Answer } from '@/lib/interview';
import type { State, TurnView } from '@/lib/session';
import { Agent, Alert, Check, Clock, Undo } from '../../icons';

type Busy = null | 'answer' | 'wrap' | 'more' | 'back' | 'finish';

export default function Interview({ initial }: { initial: State }) {
  const [state, setState] = useState(initial);
  const [busy, setBusy] = useState<Busy>(null);
  const [pending, setPending] = useState<Answer | null>(null);
  const [error, setError] = useState('');
  const [moved, setMoved] = useState(false); // animate the card only after a step change, never on page load
  const [restore, setRestore] = useState<{ id: string; answer: Answer } | null>(null); // "이전" fills the reopened question back in

  async function send(action: Exclude<Busy, null>, extra: Record<string, unknown> = {}) {
    setBusy(action);
    setError('');
    setMoved(true);
    try {
      const res = await fetch(`/api/sessions/${state.id}`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ action, ...extra }) });
      const data = await res.json().catch(() => ({ error: '서버 응답을 읽지 못했어요.' }));
      if (!res.ok) throw new Error(data.error ?? '처리하지 못했어요.');
      setState(data as State);
      if (action === 'finish') window.scrollTo({ top: 0 });
    } catch (e) {
      setError((e as Error).message || '연결이 끊겼어요. 다시 시도해 주세요.');
    } finally {
      setBusy(null);
      setPending(null);
    }
  }

  function back() {
    const last = state.turns.filter((t) => t.answer).at(-1);
    setRestore(last?.answer ? { id: last.id, answer: last.answer } : null);
    send('back');
  }

  if (state.status === 'done' && state.result) return <Result state={state} />;

  const answered = state.turns.filter((t) => t.answer || (pending && t.id === state.open?.id)).map((t) => (t.answer ? t : { ...t, answer: pending }));
  const waiting = busy === 'answer' || busy === 'more';
  const asked = state.turns.length;

  return (
    <div className="layout">
      <div className="layout__main">
        <div className="page-head">
          <div className="page-head__text">
            <h1 className="prompt-title">{state.prompt}</h1>
            <p className="page-head__desc">질문에 답할수록 오른쪽의 애매한 부분이 줄어들어요. 최대 {state.maxQuestions}개까지 물어봐요.</p>
          </div>
        </div>

        <ol className="flow" aria-label="질문 워크플로우">
          {answered.map((t) => <Step key={t.id} turn={t} />)}
          <li className="flow__step flow__step--current">
            <span className="flow__node num" aria-hidden="true">{waiting ? asked + 1 : state.open ? state.open.idx + 1 : <Check />}</span>
            <div className="flow__body">
              {waiting && <Loading label={busy === 'answer' ? '다음 질문을 만드는 중이에요.' : '질문을 하나 더 만드는 중이에요.'} />}
              {state.open ? (
                // Stays mounted (hidden) while the answer is sent, so a failed request gives back the picked options and typed text.
                <div hidden={waiting}>
                  <QuestionCard
                    key={state.open.id} turn={state.open} max={state.maxQuestions} enter={moved} busy={busy} error={error}
                    onAnswer={(a) => { setPending(a); send('answer', { turnId: state.open!.id, ...a }); }}
                    initialAnswer={restore?.id === state.open.id ? restore.answer : null}
                    onBack={back} onWrap={() => send('wrap')}
                  />
                </div>
              ) : waiting ? null : state.restate ? (
                <Restate restate={state.restate} enter={moved} busy={busy} error={error} onFinish={() => send('finish')} onMore={() => send('more')} onBack={back} />
              ) : (
                <div className="notice notice--error" role="alert"><Alert /><p>다음 단계를 불러오지 못했어요. 새로 고쳐 주세요.</p></div>
              )}
            </div>
          </li>
        </ol>
      </div>
      <Ledger state={state} current={waiting ? null : state.open?.track ?? null} />
    </div>
  );
}

function Step({ turn }: { turn: TurnView }) {
  return (
    <li className="flow__step">
      <span className="flow__node num" aria-hidden="true">{turn.idx + 1}</span>
      <div className="flow__body">
        <ol className="chat">
          <li className="msg msg--agent">
            <p className="msg__who"><Agent />질문 {turn.idx + 1}<span className="flow__track">{turn.trackLabel}</span></p>
            <div className="msg__body"><p>{turn.question}</p></div>
          </li>
          <li className="msg msg--user">
            <p className="msg__who visually-hidden">내 답</p>
            <div className="msg__body"><p>{decisionOf(turn)}</p></div>
          </li>
        </ol>
      </div>
    </li>
  );
}

function Loading({ label }: { label: string }) {
  return (
    <section className="panel qcard" aria-busy="true" aria-label={label}>
      <div className="panel__body qcard__body">
        <p className="meta" role="status">{label} LLM을 쓰면 30초쯤 걸려요.</p>
        <span className="skeleton" style={{ width: '80%' }} />
        <span className="skeleton" style={{ width: '55%' }} />
        <span className="skeleton qcard__skel-chip" style={{ width: '45%' }} />
        <span className="skeleton qcard__skel-chip" style={{ width: '50%' }} />
        <span className="skeleton qcard__skel-chip" style={{ width: '40%' }} />
      </div>
    </section>
  );
}

function ErrorNotice({ error }: { error: string }) {
  return error ? <div className="notice notice--error" role="alert"><Alert /><p>{error}</p></div> : null;
}

function QuestionCard({ turn, max, enter, busy, error, initialAnswer, onAnswer, onBack, onWrap }: {
  turn: TurnView; max: number; enter: boolean; busy: Busy; error: string; initialAnswer: Answer | null;
  onAnswer: (a: Answer) => void; onBack: () => void; onWrap: () => void;
}) {
  const [choices, setChoices] = useState<string[]>(() => (initialAnswer?.recommended ? [RECOMMEND] : initialAnswer?.choices ?? []));
  const [text, setText] = useState(initialAnswer?.text ?? '');
  const [empty, setEmpty] = useState(false);
  const heading = useRef<HTMLHeadingElement>(null);
  const all = [...turn.options, RECOMMEND];
  const locked = busy !== null;

  // Move focus to each new question (not on first page load) so keyboard and screen-reader users land on it.
  useEffect(() => {
    if (!enter) return;
    heading.current?.focus({ preventScroll: true });
    heading.current?.scrollIntoView({ block: 'nearest' });
  }, [turn.idx, enter]);

  function toggle(o: string) {
    setEmpty(false);
    if (!turn.multi) return setChoices([o]);
    setChoices((c) => (c.includes(o) ? c.filter((x) => x !== o) : o === RECOMMEND ? [o] : [...c.filter((x) => x !== RECOMMEND), o]));
  }

  function submit(e?: FormEvent) {
    e?.preventDefault();
    if (locked) return;
    if (!choices.length && !text.trim()) return setEmpty(true);
    onAnswer({ choices, text: text.trim() });
  }

  function keys(e: KeyboardEvent<HTMLFormElement>) {
    if ((e.target as HTMLElement).tagName === 'TEXTAREA' || e.metaKey || e.ctrlKey || e.altKey) return;
    const n = Number(e.key);
    if (n >= 1 && n <= all.length) { e.preventDefault(); toggle(all[n - 1]); }
  }

  const fallback = turn.provider.startsWith('mock (');
  return (
    <section className={`panel qcard${enter ? ' qcard--enter' : ''}`} aria-labelledby={`q-${turn.id}`}>
      <form onSubmit={submit} onKeyDown={keys} noValidate>
        <div className="panel__body qcard__body">
          <p className="meta num">질문 {turn.idx + 1} / {max}<span className="flow__track">{turn.trackLabel}</span></p>
          <h2 className="qcard__q" id={`q-${turn.id}`} ref={heading} tabIndex={-1}>{turn.question}</h2>
          {turn.hint && <p className="qcard__hint">{turn.hint}</p>}
          <fieldset className="choices choices--stack" disabled={locked} aria-describedby={empty ? `e-${turn.id}` : undefined}>
            <legend>{turn.multi ? '여러 개 골라도 돼요' : '하나만 골라 주세요'}</legend>
            {all.map((o, i) => (
              <label className={`chip${o === RECOMMEND ? ' chip--recommend' : ''}`} key={o}>
                <input type={turn.multi ? 'checkbox' : 'radio'} name={`choice-${turn.id}`} value={o} checked={choices.includes(o)} onChange={() => toggle(o)} />
                <Check className="chip__check" />
                <span className="chip__key num" aria-hidden="true">{i + 1}</span>
                {o}
              </label>
            ))}
          </fieldset>
          {turn.allowFree && (
            <div className="field">
              <label className="field__label" htmlFor={`t-${turn.id}`}>직접 쓰기</label>
              <textarea
                className="textarea qcard__text" id={`t-${turn.id}`} rows={2} maxLength={500} disabled={locked}
                placeholder="예: 둘 다 좋은데, 밤에는 분위기가 바뀌었으면 해요" value={text}
                onChange={(e) => { setText(e.target.value); setEmpty(false); }}
                onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); submit(); } }}
                aria-describedby={`h-${turn.id}${empty ? ` e-${turn.id}` : ''}`} aria-invalid={empty || undefined}
              />
              <p className="field__help" id={`h-${turn.id}`}>보기와 함께 써도 돼요. Enter로 보내고 Shift+Enter로 줄을 바꿔요. 숫자 키로 보기를 고를 수 있어요.</p>
            </div>
          )}
          {empty && <p className="field__error" id={`e-${turn.id}`}>보기를 고르거나 직접 써 주세요.</p>}
          {fallback && <p className="meta">{turn.provider}로 만든 질문이에요.</p>}
          <ErrorNotice error={error} />
        </div>
        <footer className="panel__foot btn-row">
          <button type="submit" className="btn btn--primary" disabled={locked} aria-busy={busy === 'answer'}>다음 질문</button>
          {turn.idx > 0 && <button type="button" className="btn btn--ghost" onClick={onBack} disabled={locked} aria-busy={busy === 'back'}><Undo />이전</button>}
          {turn.idx > 0 && <button type="button" className="btn btn--ghost qcard__wrap" onClick={onWrap} disabled={locked} aria-busy={busy === 'wrap'}>여기까지로 정리하기</button>}
        </footer>
      </form>
    </section>
  );
}

function Restate({ restate, enter, busy, error, onFinish, onMore, onBack }: {
  restate: NonNullable<State['restate']>; enter: boolean; busy: Busy; error: string; onFinish: () => void; onMore: () => void; onBack: () => void;
}) {
  const heading = useRef<HTMLHeadingElement>(null);
  useEffect(() => { if (enter) heading.current?.focus({ preventScroll: true }); }, [enter]);
  const locked = busy !== null;
  return (
    <section className={`panel qcard${enter ? ' qcard--enter' : ''}`} aria-labelledby="restate-h" aria-busy={busy === 'finish'}>
      <div className="panel__body qcard__body">
        <h2 className="qcard__q" id="restate-h" ref={heading} tabIndex={-1}>이대로 정리할까요?</h2>
        <p className="qcard__goal">{restate.goal}</p>
        <dl className="decisions">
          {restate.decisions.map((d) => (
            <div key={d.track}><dt>{d.track}</dt><dd>{d.decision}</dd></div>
          ))}
        </dl>
        {restate.fuzzy.length > 0 && <p className="meta">아직 정하지 않은 것: {restate.fuzzy.join(', ')}</p>}
        {busy === 'finish' && <div className="notice" role="status"><Clock /><p>게임 이름과 설명을 정리하는 중이에요. LLM을 쓰면 30초쯤 걸려요.</p></div>}
        <ErrorNotice error={error} />
      </div>
      <footer className="panel__foot btn-row">
        <button type="button" className="btn btn--primary" onClick={onFinish} disabled={locked} aria-busy={busy === 'finish'}>이대로 정리하기</button>
        {restate.canAskMore && <button type="button" className="btn" onClick={onMore} disabled={locked}>질문 하나 더</button>}
        <button type="button" className="btn btn--ghost" onClick={onBack} disabled={locked} aria-busy={busy === 'back'}><Undo />이전</button>
      </footer>
    </section>
  );
}

function Ledger({ state, current }: { state: State; current: string | null }) {
  return (
    <aside className="panel layout__side ledger" aria-labelledby="ledger-h">
      <header className="panel__head"><h2 className="panel__title" id="ledger-h">애매한 부분</h2></header>
      <div className="panel__body">
        <p className="ledger__total">
          <span className="ledger__num num">{state.overall.toFixed(2)}</span>
          <span className="meta">전체 애매함이에요. 0.20 이하가 되면 정리해요.</span>
        </p>
        <ul className="ledger__list">
          {state.ledger.map((l) => (
            <li className="ledger__row" key={l.key} data-clear={l.clear} aria-current={l.key === current ? 'step' : undefined}>
              <span className="ledger__label">{l.label}{l.key === current && <span className="visually-hidden">, 지금 묻는 중</span>}</span>
              <span className="ledger__state">{l.clear ? <><Check />명확</> : '애매'}</span>
              <span className="ledger__bar" aria-hidden="true"><span style={{ transform: `scaleX(${l.score})` }} /></span>
              <span className="ledger__score num">{l.score.toFixed(2)}</span>
            </li>
          ))}
        </ul>
        <p className="meta">0은 정해졌다는 뜻, 1은 아직 모른다는 뜻이에요.</p>
      </div>
    </aside>
  );
}

function Result({ state }: { state: State }) {
