  if (fz) {
    await fz.click(); await sleep(800);
    console.log('after freeze', await page.$$eval('.node', (n) => n.map((x) => x.dataset.status).join(',')));
    const f = await page.$('.node[data-status="frozen"]');
    if (f) await f.screenshot({ path: process.env.S + '/shots/wf-node-frozen.png' });
