  // focus ring check: tab to first expand button
  await page.keyboard.press('Tab'); await page.keyboard.press('Tab'); await page.keyboard.press('Tab');
  await shot('wf-focus-d', false);
  await size(390, 844);
  await page.goto(url, { waitUntil: 'networkidle0' }); await sleep(800);
  await shot('wf-canvas-m', false);
  console.log('m overflow', await overflow());
  const eb = await page.$('.node button[aria-expanded="false"]');
  if (eb) { await eb.click(); await sleep(1000); }
  await shot('wf-expanded-m', false);
};

