export default async ({ page, shot, size, sleep }) => {
  const S = process.env.S;
  await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 2 });
  await page.goto('http://localhost:3102/', { waitUntil: 'networkidle0' });
  await sleep(1000);
  // collapse all expanded cards except one with a gallery
  for (const b of await page.$$('.node button[aria-expanded="true"]')) {
    const hasGal = await b.evaluate((el) => !!el.closest('.node').querySelector('.gallery'));
    if (!hasGal) { await b.click(); await sleep(400); }
  }
  // zoom to 1 on the gallery node: double-click empty canvas won't help; use fitView via keyboard? Use controls zoom-in
  const gnode = await page.$('.node:has(.gallery)');
  if (!gnode) { console.log('no gallery node'); return; }
  const box = await gnode.boundingBox();
  console.log('gallery node box', box);
  // Zoom by wheel over the node
  await page.mouse.move(box.x + box.width / 2, box.y + 40);
  for (let i = 0; i < 4; i++) { await page.mouse.wheel({ deltaY: -120 }); await sleep(150); }
  await sleep(600);
  await shot('wf-zoom-d', false);
  const g = await page.$('.node:has(.gallery)');
  await g.screenshot({ path: S + '/shots/wf-gnode-slide.png' });
  await page.click('.node:has(.gallery) .seg button:nth-child(2)'); await sleep(600);
  await (await page.$('.node:has(.gallery)')).screenshot({ path: S + '/shots/wf-gnode-grid.png' });
  // open lightbox on first image tile
  const tile = await page.$('.node:has(.gallery) .preview__btn');
  if (tile) { await tile.click(); await sleep(700); await shot('wf-lightbox', false); await page.keyboard.press('Escape'); await sleep(300); }
  // freeze it then capture
  const fz = await page.$('.node:has(.gallery)[data-status="active"] .node__actions .btn:not(.btn--ghost)');
  if (fz) { await fz.click(); await sleep(900); await (await page.$('.node:has(.notice), .node[data-expanded="true"]')).screenshot({ path: S + '/shots/wf-gnode-frozen.png' }); }
  const undo = await page.$('.node[data-expanded="true"] .node__actions .btn--ghost');
  if (undo) { await undo.click(); await sleep(900); }
  console.log('status after undo', await page.$$eval('.node[data-expanded="true"]', (n) => n.map((x) => x.dataset.status)));
  // cancel it to see cancelled state, then undo back
  const cancel = await page.$('.node[data-expanded="true"][data-status="active"] .node__actions .btn--ghost:not(.btn--icon)');
  if (cancel) { await cancel.click(); await sleep(900); await (await page.$('.node[data-expanded="true"]')).screenshot({ path: S + '/shots/wf-gnode-cancel.png' }); const u = await page.$('.node[data-expanded="true"] .node__actions .btn--ghost:not(.btn--icon)'); await u.click(); await sleep(700); }
  console.log('final', await page.$$eval('.node[data-expanded="true"]', (n) => n.map((x) => x.dataset.status)));
  // keyboard focus: focus expand button
  await page.focus('.node[data-expanded="true"] .btn--icon');
  await page.keyboard.press('Shift+Tab'); await sleep(200);
  await (await page.$('.node[data-expanded="true"]')).screenshot({ path: S + '/shots/wf-gnode-focus.png' });
};

