export default async ({ page, shot, size, overflow, sleep }) => {
  page.on('response', (r) => { if (r.status() >= 400) console.log('HTTP', r.status(), r.url()); });
  const url = process.env.PD_URL || 'http://localhost:3103/';
  await size(1440, 900);
  await page.goto(url, { waitUntil: 'networkidle0' });
  await sleep(800);
  await shot('pd-home-d');
  const gen = await page.$('.plan-go .btn--primary');
  const dis = await gen.evaluate((b) => b.disabled);
  console.log('generate disabled?', dis);
  if (!dis) { await gen.click(); await page.waitForFunction(() => !document.querySelector('.plan-go .btn--primary[aria-busy="true"]'), { timeout: 60000 }); await sleep(1200); }
  await shot('pd-gen-d');
  console.log('imgs in preview', await page.$$eval('.md-doc img', (a) => a.map((i) => `${i.complete && i.naturalWidth > 0 ? 'ok' : 'BROKEN'} ${i.getAttribute('src')}`)));
  for (const t of ['markdown', 'split']) {
    const b = await page.$(`#t-${t}`);
    if (b) { await b.click(); await sleep(700); await shot(`pd-tab-${t}-d`, false); }
  }
  // keyboard arrow on tabs
  await page.focus('#t-split'); await page.keyboard.press('ArrowRight'); await sleep(300);
  console.log('after ArrowRight selected', await page.$eval('[role=tab][aria-selected=true]', (e) => e.id), 'focused', await page.evaluate(() => document.activeElement.id));
  await page.click('#t-preview'); await sleep(400);
  await size(390, 844); await sleep(500);
  await shot('pd-gen-m');
  console.log('m overflow', await overflow());
  await page.click('#t-markdown'); await sleep(500);
  await shot('pd-tab-markdown-m');
  console.log('m md overflow', await overflow());
};

