export default async ({ page, sleep }) => {
  page.on('requestfailed', (r) => console.log('FAILED', r.url(), r.failure()?.errorText));
  page.on('response', (r) => { if (r.url().includes('.svg')) console.log('RESP', r.status(), r.url()); });
  await page.setViewport({ width: 1440, height: 900 });
  await page.goto('http://localhost:3103/', { waitUntil: 'networkidle0' });
  await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 400) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 60)); } });
  await sleep(1500);
  console.log(JSON.stringify(await page.$$eval('img', (a) => a.filter((i) => i.src.includes('svg')).map((i) => ({ src: i.getAttribute('src'), c: i.complete, nw: i.naturalWidth, w: i.clientWidth, h: i.clientHeight, op: getComputedStyle(i).opacity, vis: getComputedStyle(i).visibility, d: getComputedStyle(i).display }))), null, 0));
};

