export default async ({ page, shot, sleep }) => {
  await page.emulateMediaFeatures([{ name: 'prefers-color-scheme', value: 'light' }]);
  await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 1 });
  const s1 = process.env.S1;
  // step1 home + keyboard focus on example chip
  await page.goto('http://localhost:3101/', { waitUntil: 'networkidle0' });
  for (let i = 0; i < 6; i++) await page.keyboard.press('Tab');
  await shot('l-s1-home', false);
  console.log('s1 focus', await page.evaluate(() => { const a = document.activeElement; const cs = getComputedStyle(a); return `${a.tagName}.${a.className} outline=${cs.outlineStyle} ${cs.outlineWidth} ${cs.outlineColor}`; }));
  await page.goto(`http://localhost:3101/s/${s1}`, { waitUntil: 'networkidle0' });
  await shot('l-s1-result', false);
  // a fresh interview question in light
  await page.goto('http://localhost:3101/', { waitUntil: 'networkidle0' });
  await page.type('#prompt', '좀비가 나오는 편의점에서 하룻밤 버티기');
  await Promise.all([page.waitForNavigation({ waitUntil: 'networkidle0' }), page.click('button[type=submit]')]);
  await page.click('.choices .chip'); await sleep(200);
  await page.focus('.choices .chip:nth-of-type(2) input'); await sleep(100);
  await shot('l-s1-q', false);
  console.log('session2', page.url());
  // workflow
  await page.goto('http://localhost:3102/', { waitUntil: 'networkidle0' }); await sleep(800);
  await shot('l-wf', false);
  await page.focus('.node button.btn--icon'); await sleep(100);
  const n = await page.$('.react-flow__node:has(button.btn--icon:focus)');
  if (n) await n.screenshot({ path: process.env.S + '/shots/l-wf-focus.png' });
  // plan-doc
  await page.goto('http://localhost:3103/', { waitUntil: 'networkidle0' }); await sleep(600);
  await shot('l-pd', false);
  await page.focus('#t-preview'); await page.keyboard.press('ArrowRight'); await sleep(400);
  console.log('pd tab after ArrowRight', await page.$eval('[role=tab][aria-selected=true]', (e) => e.id), await page.evaluate(() => document.activeElement.id));
  await shot('l-pd-tab', false);
};

